-- Messages for the staff inbox (text only; add photos live during a demo).
select b.id, x.topic::public.submission_topic, x.message, a.donor_name, a.contact_email,
       x.status::public.submission_status, x.staff_notes, now() - make_interval(days => x.days_ago, hours => x.n)
from (values
  ('VCP-0417', 'plaque', 'The plaque was installed this morning — it looks beautiful. Thank you all so much!', 'resolved', null, 20, 1),
  ('VCP-0406', 'damage', 'Two slats on the backrest are cracked and one bolt is missing.', 'in_progress', 'Sent to maintenance', 6, 2),
  ('VCP-0218', 'question', 'When will the plaque for our bench go up? We submitted the text in the spring.', 'new', null, 2, 3),
  ('VCP-0519', 'bench_photo', 'Visited our bench on Grandpa''s birthday. Sharing how it looks in the fall.', 'new', null, 1, 4),
  ('VCP-0202', 'damage', 'Graffiti on the seat and the plaque is scratched.', 'new', null, 0, 5),
  ('VCP-0242', 'plaque', 'Could we fix a typo on our plaque? The honoree''s last name is misspelled.', 'in_progress', null, 9, 6),
  ('VCP-0284', 'question', 'Is it possible to renew for another 5 years before the current term ends?', 'resolved', null, 30, 7)
) as x(code, topic, message, status, staff_notes, days_ago, n)
join public.benches b on b.code = x.code
join lateral (
  select donor_name, contact_email from public.adoptions
  where bench_id = b.id and status = 'approved' and starts_on <= current_date and ends_on > current_date
  limit 1
) a on true;

commit;
